test("executor retains cancellation requested before reconciled turn identity",async()=>{const root=await mkdtemp(join(tmpdir(),"adt-executor-early-cancel-")),entered=deferred(),identity=deferred(),finish=deferred(),interrupted=deferred(),logs=[],original=console.log;let interrupts=0,runs=0;const app={readiness:async()=>true,runWorkflowTurn:async value=>{runs++;entered.resolve();await identity.promise;value.onStarted("thread-existing","turn-existing");await finish.promise;return{ok:true,outputText:"PRIVATE MODEL OUTPUT",threadId:"thread-existing",turnId:"turn-existing"}},interruptWorkflowTurn:async(threadId,turnId)=>{interrupts++;assert.deepEqual([threadId,turnId],["thread-existing","turn-existing"]);interrupted.resolve()},close:async()=>{}};console.log=value=>logs.push(String(value));const server=createExecutorServer(executorConfiguration(root),app),base=await listen(server);try{const started=await (await signedExecutorFetch(base,"/internal/v1/executions","POST",{cwd:root,sandbox:"workspace-write",prompt:"PRIVATE PROMPT"})).json(),path=`/internal/v1/executions/${started.executionId}`;await entered.promise;assert.equal((await (await signedExecutorFetch(base,path+"/cancel","POST")).json()).state,"cancelling");assert.equal((await (await signedExecutorFetch(base,path)).json()).state,"cancelling");assert.equal(interrupts,0);identity.resolve();await interrupted.promise;assert.equal(interrupts,1);assert.equal((await (await signedExecutorFetch(base,path+"/cancel","POST")).json()).state,"cancelling");assert.equal(interrupts,1);finish.resolve();await until(async()=>(await (await signedExecutorFetch(base,path)).json()).state==="cancelled","executor cancellation did not settle");assert.equal(runs,1);assert.doesNotMatch(logs.join("\n"),/PRIVATE PROMPT|PRIVATE MODEL OUTPUT|workspace|cwd|token|credential|turn\/start/);assert.ok(logs.some(line=>line.includes('runner_execution_cancellation_requested')))}finally{console.log=original;identity.resolve();finish.resolve();await close(server);await rm(root,{recursive:true,force:true})}});

test("executor cancellation after known turn identity interrupts once and wins over success",async()=>{const root=await mkdtemp(join(tmpdir(),"adt-executor-known-cancel-")),startedTurn=deferred(),finish=deferred();let interrupts=0;const app={readiness:async()=>true,runWorkflowTurn:async input=>{input.onStarted("thread-known","turn-known");startedTurn.resolve();await finish.promise;return{ok:true,outputText:"done",threadId:"thread-known",turnId:"turn-known"}},interruptWorkflowTurn:async()=>{interrupts++},close:async()=>{}};const server=createExecutorServer(executorConfiguration(root),app),base=await listen(server);try{const started=await (await signedExecutorFetch(base,"/internal/v1/executions","POST",{cwd:root,sandbox:"workspace-write",prompt:"p"})).json(),path=`/internal/v1/executions/${started.executionId}`;await startedTurn.promise;assert.equal((await (await signedExecutorFetch(base,path+"/cancel","POST")).json()).state,"cancelling");assert.equal(interrupts,1);finish.resolve();await until(async()=>(await (await signedExecutorFetch(base,path)).json()).state==="cancelled","known cancellation did not settle");assert.equal(interrupts,1)}finally{finish.resolve();await close(server);await rm(root,{recursive:true,force:true})}});

test("split controller cancellation survives executor turn identity reconciliation",async()=>{const {RemoteExecutorClient}=await import("../dist/executor.js"),{PersistentCodexJobRunner}=await import("../dist/job-runner.js"),root=await mkdtemp(join(tmpdir(),"adt-split-reconcile-cancel-")),entered=deferred(),identity=deferred(),finish=deferred(),interrupted=deferred();let executions=0,interrupts=0;const executorApp={readiness:async()=>true,status:async()=>({account:{type:"chatgpt"}}),listModels:async()=>[{id:"m",threadModel:"m",displayName:"M",isDefault:true,defaultReasoningEffort:"medium",supportedReasoningEfforts:[]}],runWorkflowTurn:async input=>{executions++;entered.resolve();await identity.promise;input.onStarted("thread-one","turn-one");await finish.promise;return{ok:true,outputText:"late success",threadId:"thread-one",turnId:"turn-one"}},interruptWorkflowTurn:async()=>{interrupts++;interrupted.resolve()},close:async()=>{}};const server=createExecutorServer(executorConfiguration(root),executorApp),base=await listen(server),remote=new RemoteExecutorClient(base,privateKey),runner=await PersistentCodexJobRunner.create(remote,[{key:"repo",name:"Repo",cwd:root,enabled:true,ready:true,sandbox:"workspace-write"}],join(root,"jobs"),1000,100,undefined,true,true);let job;try{job=await runner.start({idempotencyKey:"split-cancel",environmentKey:"repo",prompt:"private"});await entered.promise;assert.equal((await runner.cancel(job.jobId)).state,"cancellation_pending");identity.resolve();await interrupted.promise;assert.equal(interrupts,1);finish.resolve();await until(()=>runner.get(job.jobId).state==="cancelled","controller job did not settle cancelled");assert.equal(executions,1);assert.equal(interrupts,1)}finally{identity.resolve();finish.resolve();await close(server);await rm(root,{recursive:true,force:true})}});

test("unresolved split cancellation remains pending until hard-stop quiescence",async()=>{
 const {RemoteExecutorClient}=await import("../dist/executor.js"),{PersistentCodexJobRunner}=await import("../dist/job-runner.js"),{StdioAppServerClient}=await import("../dist/app-server-client.js"),{EventEmitter}=await import("node:events"),{PassThrough}=await import("node:stream"),root=await mkdtemp(join(tmpdir(),"adt-split-unresolved-cancel-")),requests=[],turnSent=deferred(),escalated=deferred(),replacementReady=deferred(),input=new PassThrough(),output=new PassThrough(),child=Object.assign(new EventEmitter(),{stdin:input,stdout:output,stderr:new PassThrough(),killed:false,kill(){this.killed=true;this.emit("exit",0)}}),reply=(id,result)=>output.write(JSON.stringify({id,result})+"\n");
 input.on("data",chunk=>{for(const line of chunk.toString().trim().split("\n")){const request=JSON.parse(line);requests.push(request);if(request.method==="initialize")reply(request.id,{});if(request.method==="account/read")reply(request.id,{account:{type:"chatgpt"}});if(request.method==="model/list")reply(request.id,{data:[{id:"m",model:"m",displayName:"M",isDefault:true,defaultReasoningEffort:"medium",supportedReasoningEfforts:[]}]});if(request.method==="thread/start")reply(request.id,{thread:{id:"thread-unresolved"}});if(request.method==="turn/start")turnSent.resolve()}});
 const app=new StdioAppServerClient("codex","test",5,()=>child,100,10,[],20,20,10),serverA=createExecutorServer(executorConfiguration(root),app),base=await listen(serverA),port=Number(new URL(base).port);let serverB,stoppedA=false,replacementFailure,job;
 const hardStop=async()=>{escalated.resolve();try{await close(serverA);stoppedA=true;serverB=createExecutorServer(executorConfiguration(root),{readiness:async()=>true,close:async()=>{}});await new Promise((resolve,reject)=>serverB.listen(port,"127.0.0.1",error=>error?reject(error):resolve()))}catch(error){replacementFailure=error}finally{replacementReady.resolve()}};
 const remote=new RemoteExecutorClient(base,privateKey),runner=await PersistentCodexJobRunner.create(remote,[{key:"repo",name:"Repo",cwd:root,enabled:true,ready:true,sandbox:"workspace-write"}],join(root,"jobs"),1000,20,undefined,true,true,hardStop);
 try{job=await runner.start({idempotencyKey:"unresolved-cancel",environmentKey:"repo",prompt:"private"});await turnSent.promise;assert.equal((await runner.cancel(job.jobId)).state,"cancellation_pending");const active=await (await signedExecutorFetch(base,"/internal/v1/status")).json(),path=`/internal/v1/executions/${active.activeExecutionId}`;assert.equal((await (await signedExecutorFetch(base,path)).json()).state,"cancelling");assert.equal(requests.filter(x=>x.method==="turn/start").length,1);assert.equal(requests.filter(x=>x.method==="turn/interrupt").length,0);assert.equal((await signedExecutorFetch(base,"/internal/v1/executions","POST",{cwd:root,sandbox:"workspace-write",prompt:"second"})).status,409);await escalated.promise;await replacementReady.promise;if(replacementFailure)throw replacementFailure;await until(()=>runner.get(job.jobId).state==="cancelled","generation replacement did not settle controller cancellation");assert.equal(requests.filter(x=>x.method==="turn/start").length,1);assert.equal(requests.filter(x=>x.method==="turn/interrupt").length,0);assert.equal(runner.list(1).capacity.activeJobId,null)}finally{if(!stoppedA)await close(serverA);if(serverB)await close(serverB);await rm(root,{recursive:true,force:true})}
});

